// Repository-owned programs shared with the installed-rustc oracle.
export const enumRecordCases = [
  ['enum record field layout differs from initializer order', `enum E{R{x:i32,y:i32},End}fn n(x:i32)->i32{print!("{}",x);x}fn main(){let e=E::R{y:n(2),x:n(1)};println!(" {}",match e{E::R{x,y}=>x*10+y,E::End=>0});}`, '21 12\n'],
  ['empty record tuple and unit enum variants retain distinct syntax', `enum E{R{},T(),U}fn main(){let a=E::R{};let b=E::T{};let c=E::U{};println!("{} {} {}",match a{E::R{}=>1,_=>0},match b{E::T()=>2,_=>0},match c{E::U{}=>3,_=>0});}`, '1 2 3\n'],
  ['numeric tuple enum brace fields use positional payloads', `enum E{T(i32,bool)}fn main(){let e=E::T{1:true,0:7};let E::T{1:b,0:x}=e;println!("{} {}",x,b);}`, '7 true\n'],
  ['record shorthand and renamed field bindings', `enum E{R{x:i32,y:bool}}fn main(){let x=7;let e=E::R{x,y:true};let E::R{x:n,y:b}=e;println!("{} {}",n,b);}`, '7 true\n'],
  ['record let pattern mutable shorthand', `enum E{R{x:i32}}fn main(){let E::R{mut x}=E::R{x:7};x+=1;println!("{}",x);}`, '8\n'],
  ['nested records in tuple and Option patterns', `enum E{R{value:Option<(i32,bool)>},End}fn main(){let e=E::R{value:Some((7,true))};println!("{}",match e{E::R{value:Some((x,true))}=>x,E::R{value:Some((_,false))}=>2,E::R{value:None}=>3,E::End=>4});}`, '7\n'],
  ['record or patterns select payload of the matching variant', `enum E{A{x:i32},B{y:i32},End}fn f(e:E)->i32{match e{E::A{x:n}|E::B{y:n}=>n,E::End=>0}}fn main(){println!("{} {}",f(E::A{x:7}),f(E::B{y:8}));}`, '7 8\n'],
  ['record predicate must guard payload projection by discriminant', `enum E{A{x:Option<i32>},B{flag:bool}}fn main(){let e=E::B{flag:true};println!("{}",match e{E::A{x:Some(n)}=>n,E::A{x:None}=>0,E::B{flag:true}=>9,E::B{flag:false}=>2});}`, '9\n'],
  ['record payload boolean coverage is structural', `enum E{R{a:bool,b:bool}}fn f(e:E)->i32{match e{E::R{a:true,..}=>1,E::R{a:false,b:true}=>2,E::R{a:false,b:false}=>3}}fn main(){println!("{} {}",f(E::R{a:false,b:true}),f(E::R{a:false,b:false}));}`, '2 3\n'],
  ['record if-let and let-else preserve failure scope', `enum E{R{x:i32},End}fn f(e:E)->i32{let E::R{x}=e else{return 3;};x}fn main(){if let E::R{x}=(E::R{x:9}){println!("{} {}",x,f(E::End));}}`, '9 3\n'],
  ['record while-let repeatedly extracts new payload', `enum E{R{x:i32},End}fn main(){let mut e=E::R{x:3};while let E::R{x}=e{print!("{}",x);e=if x>1{E::R{x:x-1}}else{E::End};}}`, '321'],
  ['public enum fields inherit enum visibility', `mod m{pub enum E{R{x:i32}}}fn main(){let m::E::R{x}=m::E::R{x:8};println!("{}",x);}`, '8\n'],
  ['imported renamed record variant and enum type alias', `mod m{pub enum E{R{x:i32}}}use m::E::R as Make;type A=m::E;fn main(){let Make{x:a}=Make{x:3};let A::R{x:b}=A::R{x:4};println!("{} {}",a,b);}`, '3 4\n'],
  ['generic record argument inference and context', `enum E<T>{R{x:T},End}fn main(){let e:E<u8>=E::R{x:7};let a=E::R{x:300u16};println!("{} {}",match e{E::R{x}=>x,_=>0},match a{E::R{x}=>x,_=>0});}`, '7 300\n'],
  ['generic record explicit arguments on variant', `enum E<T>{R{x:T}}fn main(){let E::R{x}=E::R::<u16>{x:300};println!("{}",x);}`, '300\n'],
  ['enum where predicates and inline bounds', `enum E<T>where T:Copy{R{x:T}}enum F<T:Copy>{V(T)}fn main(){let E::R{x}=E::R{x:7};let F::V(y)=F::V(9u8);println!("{} {}",x,y);}`, '7 9\n'],
  ['record fields resolve types in declaration namespace', `mod m{pub struct S(pub i32);pub enum E{R{s:S}}}fn main(){let m::E::R{s}=m::E::R{s:m::S(6)};println!("{}",s.0);}`, '6\n'],
  ['const record values round trip through MIR', `enum E{R{x:i32,y:bool}}const X:E=E::R{y:true,x:3*7};const fn f(e:E)->i32{let E::R{x,..}=e;x}const N:i32=f(X);fn main(){let E::R{x,y}=X;println!("{} {} {}",x,y,N);}`, '21 true 21\n'],
  ['record const assignment uses selected payloads', `enum E{R{x:i32,y:i32}}const N:i32={let mut a=0;let mut b=0;E::R{y:b,x:a}=E::R{x:2,y:3};a*10+b};fn main(){println!("{}",N);}`, '23\n'],
  ['record assignment evaluates RHS then destinations in written order', `enum E{R{x:i32,y:i32}}fn p(v:i32)->i32{print!("{}",v);v}fn i(v:usize)->usize{print!("i{}",v);v}fn main(){let mut a=[0,0];E::R{y:a[i(1)],x:a[i(0)]}=E::R{y:p(2),x:p(1)};println!(" {:?}",a);}`, '21i1i0 [1, 2]\n'],
  ['record assignment has repeated destinations and omitted members', `enum E{R{x:i32,y:i32,z:i32}}fn main(){let mut n=0;E::R{y:n,x:n,..}=E::R{x:1,y:2,z:3};println!("{}",n);}`, '1\n'],
  ['record assignment indices observe previous stores', `enum E{R{i:usize,v:i32}}fn main(){let mut i=0usize;let mut a=[0,0];E::R{i,v:a[i]}=E::R{i:1,v:9};println!("{:?}",a);}`, '[0, 9]\n'],
  ['record assignee infers generic field type', `enum E<T>{R{x:T}}fn main(){let mut n=0u16;E::R{x:n}=E::R{x:300};println!("{}",n);}`, '300\n'],
  ['owned record transfers into existing destinations', `enum E{R{x:String,y:String}}fn main(){let mut a=String::from("a");let mut b=String::from("b");E::R{x:a,y:b}=E::R{x:b,y:a};println!("{} {}",a,b);}`, 'b a\n'],
  ['record copy assignments do not alias payload arrays', `#[derive(Copy,Clone)]enum E{R{x:[i32;2]}}fn main(){let e=E::R{x:[1,2]};let mut a=[0,0];E::R{x:a}=e;a[0]=9;let E::R{x:b}=e;println!("{:?} {:?}",a,b);}`, '[9, 2] [1, 2]\n'],
  ['record assignment through scalar mutable references', `enum E{R{x:i32}}fn main(){let mut n=0;let r=&mut n;E::R{x:*r}=E::R{x:7};println!("{}",*r);}`, '7\n'],
  ['record assignment classifies mutable closure captures', `enum E{R{x:i32}}fn main(){let mut n=0;let mut f=||{E::R{x:n}=E::R{x:7};};f();println!("{}",n);}`, '7\n'],
  ['record constructor divergence suppresses following effects', `enum E{R{x:i32,y:i32}}fn f()->i32{let e=E::R{y:return 8,x:{print!("bad");1}};0}fn main(){println!("{}",f());}`, '8\n'],
  ['empty record assignee and ignored payload', `enum E{R{value:i32}}enum U{R{}}fn main(){E::R{..}=E::R{value:7};U::R{}=U::R{};println!("ok");}`, 'ok\n'],
  ['cfg removes named fields before payload indexing', `enum E{R{#[cfg(any())]gone:Missing,x:i32,#[cfg(all())]y:bool}}fn main(){let E::R{y,x}=E::R{y:true,x:6};println!("{} {}",x,y);}`, '6 true\n'],
  ['cfg removes positional enum fields before numeric lookup', `enum E{T(#[cfg(any())]Missing,i32,bool)}fn main(){let E::T{1:b,0:x}=E::T{1:true,0:5};println!("{} {}",x,b);}`, '5 true\n'],
];
export const enumRecordCompileFailCases = [
  ['record variant is not a positional call', 'enum E{R{x:i32}}fn main(){let _=E::R(1);}', 'E0533'],
  ['empty record variant is not a bare value', 'enum E{R{}}fn main(){let _=E::R;}', 'E0533'],
  ['record variant is not a tuple pattern', 'enum E{R{x:i32}}fn main(){let E::R(x)=E::R{x:1};}', 'E0532'],
  ['unit variant is not a tuple pattern', 'enum E{U}fn main(){let E::U()=E::U;}', 'E0532'],
  ['missing enum record initializer field', 'enum E{R{x:i32,y:i32}}fn main(){let _=E::R{x:1};}', 'E0063'],
  ['unknown enum record initializer field', 'enum E{R{x:i32}}fn main(){let _=E::R{z:1};}', 'E0559'],
  ['duplicate enum record initializer field', 'enum E{R{x:i32}}fn main(){let _=E::R{x:1,x:2};}', 'E0062'],
  ['wrong enum record initializer type', 'enum E{R{x:i32}}fn main(){let _=E::R{x:true};}', 'E0308'],
  ['unused record variant field type is checked', 'enum E{R{x:Missing}}fn main(){}', 'E0412'],
  ['duplicate enum record declaration field', 'enum E{R{x:i32,x:bool}}fn main(){}', 'E0124'],
  ['explicit enum field visibility is illegal', 'enum E{R{pub x:i32}}fn main(){}', 'E0449'],
  ['record enum private owner remains private', 'mod m{enum E{R{x:i32}}}fn main(){let _=m::E::R{x:7};}', 'E0603'],
  ['record enum pattern must mention fields or rest', 'enum E{R{x:i32,y:i32}}fn main(){let E::R{x}=E::R{x:1,y:2};}', 'E0063'],
  ['unknown record pattern field', 'enum E{R{x:i32}}fn main(){let E::R{z}=E::R{x:1};}', 'E0559'],
  ['duplicate record pattern field', 'enum E{R{x:i32}}fn main(){let E::R{x:a,x:b}=E::R{x:1};}', 'E0062'],
  ['record pattern owner mismatch', 'enum E{R{x:i32}}enum F{R{x:i32}}fn main(){let E::R{x}=F::R{x:1};}', 'E0308'],
  ['record payload coverage cannot ignore false', 'enum E{R{x:bool}}fn main(){let _=match (E::R{x:true}){E::R{x:true}=>1};}', 'E0004'],
  ['record let is refutable with multiple variants', 'enum E{R{x:i32},U}fn main(){let E::R{x}=E::U;}', 'E0005'],
  ['record assignee requires irrefutable variant', 'enum E{R{x:i32},U}fn main(){let mut n=0;E::R{x:n}=E::U;}', 'E0005'],
  ['record assignee enforces target mutability', 'enum E{R{x:i32}}fn main(){let n=0;E::R{x:n}=E::R{x:1};}', 'E0596'],
  ['record assignment checks payload type', 'enum E{R{x:i32}}fn main(){let mut n=true;E::R{x:n}=E::R{x:1};}', 'E0308'],
  ['record enum enforces inline generic Copy bound', 'enum E<T:Copy>{R{x:T}}fn main(){let _=E::R{x:String::from("x")};}', 'E0277'],
  ['record enum enforces where Copy bound', 'enum E<T>where T:Copy{R{x:T}}fn main(){let _=E::R{x:String::from("x")};}', 'E0277'],
  ['tuple enum enforces declared bound too', 'enum E<T:Copy>{R(T)}fn main(){let _=E::R(String::from("x"));}', 'E0277'],
];
export const enumRecordPanicCases = [
  ['record initializer panic preserves source order', 'enum E{R{x:i32,y:i32}}fn main(){let _=E::R{y:{print!("y");panic!("stop")},x:{print!("bad");1}};}', 'R_PANIC', 'y'],
  ['record assignee RHS panic prevents destination effects', 'enum E{R{x:i32}}fn i()->usize{print!("bad");0}fn main(){let mut a=[0];E::R{x:a[i()]}={print!("r");panic!("stop")};}', 'R_PANIC', 'r'],
  ['record assignee later index panic preserves earlier stores', 'enum E{R{x:usize,y:i32}}fn main(){let mut i=0usize;let mut a=[0];E::R{x:i,y:a[{print!("{}",i);2}]}=E::R{x:7,y:9};}', 'R_BOUNDS', '7'],
];
